export class UriError extends Error {}

const DEFAULT_PORTS = {
  http: '80',
  ws: '80',
  https: '443',
  wss: '443',
  ftp: '21',
}

function asciiLower(s) {
  let out = ''
  for (const ch of s) {
    const code = ch.codePointAt(0)
    out += code >= 0x41 && code <= 0x5a ? String.fromCharCode(code + 0x20) : ch
  }
  return out
}

function isUnreserved(ch) {
  return /^[A-Za-z0-9\-._~]$/.test(ch)
}

// --- Splitting a reference into its five generic components ---------------

function splitScheme(s) {
  const idx = s.indexOf(':')
  if (idx === -1) return { hasScheme: false, scheme: null, rest: s }
  const before = s.slice(0, idx)
  if (/[/?#]/.test(before)) return { hasScheme: false, scheme: null, rest: s }
  return { hasScheme: true, scheme: before, rest: s.slice(idx + 1) }
}

function splitAuthority(rest) {
  if (rest.startsWith('//')) {
    let i = 2
    while (i < rest.length && !'/?#'.includes(rest[i])) i++
    return { hasAuthority: true, authority: rest.slice(2, i), rest: rest.slice(i) }
  }
  return { hasAuthority: false, authority: null, rest }
}

function splitPath(rest) {
  let i = 0
  while (i < rest.length && !'?#'.includes(rest[i])) i++
  return { path: rest.slice(0, i), rest: rest.slice(i) }
}

function splitQuery(rest) {
  if (rest.startsWith('?')) {
    let i = 1
    while (i < rest.length && rest[i] !== '#') i++
    return { hasQuery: true, query: rest.slice(1, i), rest: rest.slice(i) }
  }
  return { hasQuery: false, query: null, rest }
}

function splitFragment(rest) {
  if (rest.startsWith('#')) return { hasFragment: true, fragment: rest.slice(1) }
  return { hasFragment: false, fragment: null }
}

function splitAuthorityComponents(authority) {
  let userinfo = null
  let host = authority
  const atIdx = authority.lastIndexOf('@')
  if (atIdx !== -1) {
    userinfo = authority.slice(0, atIdx)
    host = authority.slice(atIdx + 1)
  }
  const bracketIdx = host.lastIndexOf(']')
  const searchFrom = bracketIdx === -1 ? 0 : bracketIdx
  const colonIdx = host.indexOf(':', searchFrom)
  let port = null
  let hasPort = false
  if (colonIdx !== -1) {
    hasPort = true
    port = host.slice(colonIdx + 1)
    host = host.slice(0, colonIdx)
  }
  return { userinfo, host, port, hasPort }
}

export function parseReference(str) {
  const s = splitScheme(str)
  const a = splitAuthority(s.rest)
  let userinfo = null
  let host = null
  let port = null
  let hasPort = false
  if (a.hasAuthority) {
    const ac = splitAuthorityComponents(a.authority)
    userinfo = ac.userinfo
    host = ac.host
    port = ac.port
    hasPort = ac.hasPort
  }
  const p = splitPath(a.rest)
  const q = splitQuery(p.rest)
  const f = splitFragment(q.rest)
  return {
    hasScheme: s.hasScheme,
    scheme: s.scheme,
    hasAuthority: a.hasAuthority,
    userinfo,
    host,
    hasPort,
    port,
    path: p.path,
    hasQuery: q.hasQuery,
    query: q.query,
    hasFragment: f.hasFragment,
    fragment: f.fragment,
  }
}

export function serialize(c) {
  let s = ''
  if (c.hasScheme) s += c.scheme + ':'
  if (c.hasAuthority) {
    s += '//'
    if (c.userinfo !== null) s += c.userinfo + '@'
    s += c.host
    if (c.hasPort) s += ':' + c.port
  }
  s += c.path
  if (c.hasQuery) s += '?' + c.query
  if (c.hasFragment) s += '#' + c.fragment
  return s
}

// --- Percent-encoding normalization -----------------------------------------

function normalizePercentEncoding(str, componentName) {
  let result = ''
  for (let i = 0; i < str.length; i++) {
    if (str[i] === '%') {
      const hex = str.slice(i + 1, i + 3)
      if (!/^[0-9A-Fa-f]{2}$/.test(hex)) {
        throw new UriError(`the ${componentName} has a truncated percent-encoding`)
      }
      const upperHex = hex.toUpperCase()
      const ch = String.fromCharCode(parseInt(upperHex, 16))
      result += isUnreserved(ch) ? ch : '%' + upperHex
      i += 2
    } else {
      result += str[i]
    }
  }
  return result
}

function normalizePercentEncodings(c) {
  c.path = normalizePercentEncoding(c.path, 'path')
  if (c.hasAuthority) {
    if (c.userinfo !== null) c.userinfo = normalizePercentEncoding(c.userinfo, 'userinfo')
    c.host = normalizePercentEncoding(c.host, 'host')
  }
  if (c.hasQuery) c.query = normalizePercentEncoding(c.query, 'query')
  if (c.hasFragment) c.fragment = normalizePercentEncoding(c.fragment, 'fragment')
}

// --- Dot-segment removal, RFC 3986 section 5.2.4 ----------------------------

export function removeDotSegments(path) {
  let input = path
  let output = ''
  while (input.length > 0) {
    if (input.startsWith('../')) {
      input = input.slice(3)
    } else if (input.startsWith('./')) {
      input = input.slice(2)
    } else if (input.startsWith('/./')) {
      input = '/' + input.slice(3)
    } else if (input === '/.') {
      input = '/'
    } else if (input.startsWith('/../')) {
      input = '/' + input.slice(4)
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '/..') {
      input = '/'
      output = output.replace(/\/?[^/]*$/, '')
    } else if (input === '.' || input === '..') {
      input = ''
    } else {
      const m = input.match(/^\/?[^/]*/)
      output += m[0]
      input = input.slice(m[0].length)
    }
  }
  return output
}

// --- Full normalization ------------------------------------------------------

export function normalizeComponents(c) {
  normalizePercentEncodings(c)
  if (c.hasScheme) c.scheme = asciiLower(c.scheme)
  if (c.hasAuthority) {
    c.host = asciiLower(c.host)
    if (c.hasPort) {
      const defaultPort = c.hasScheme ? DEFAULT_PORTS[c.scheme] : undefined
      if (c.port === '' || (defaultPort !== undefined && c.port === defaultPort)) {
        c.hasPort = false
        c.port = null
      }
    }
  }
  c.path = removeDotSegments(c.path)
  if (c.hasAuthority && c.path === '') c.path = '/'
}

export function normalizeReference(str) {
  const c = parseReference(str)
  normalizeComponents(c)
  return serialize(c)
}

// --- Resolution, RFC 3986 section 5.2.2, strict form -------------------------

function mergePaths(base, refPath) {
  if (base.hasAuthority && base.path === '') return '/' + refPath
  const idx = base.path.lastIndexOf('/')
  if (idx === -1) return refPath
  return base.path.slice(0, idx + 1) + refPath
}

export function resolveReference(baseStr, refStr) {
  const base = parseReference(baseStr)
  if (!base.hasScheme) throw new UriError('the base has no scheme')
  const ref = parseReference(refStr)

  let t
  if (ref.hasScheme) {
    t = {
      hasScheme: true,
      scheme: ref.scheme,
      hasAuthority: ref.hasAuthority,
      userinfo: ref.userinfo,
      host: ref.host,
      hasPort: ref.hasPort,
      port: ref.port,
      path: removeDotSegments(ref.path),
      hasQuery: ref.hasQuery,
      query: ref.query,
      hasFragment: ref.hasFragment,
      fragment: ref.fragment,
    }
  } else if (ref.hasAuthority) {
    t = {
      hasScheme: true,
      scheme: base.scheme,
      hasAuthority: true,
      userinfo: ref.userinfo,
      host: ref.host,
      hasPort: ref.hasPort,
      port: ref.port,
      path: removeDotSegments(ref.path),
      hasQuery: ref.hasQuery,
      query: ref.query,
      hasFragment: ref.hasFragment,
      fragment: ref.fragment,
    }
  } else if (ref.path === '') {
    t = {
      hasScheme: true,
      scheme: base.scheme,
      hasAuthority: base.hasAuthority,
      userinfo: base.userinfo,
      host: base.host,
      hasPort: base.hasPort,
      port: base.port,
      path: base.path,
      hasQuery: ref.hasQuery ? true : base.hasQuery,
      query: ref.hasQuery ? ref.query : base.query,
      hasFragment: ref.hasFragment,
      fragment: ref.fragment,
    }
  } else {
    const path = ref.path.startsWith('/')
      ? removeDotSegments(ref.path)
      : removeDotSegments(mergePaths(base, ref.path))
    t = {
      hasScheme: true,
      scheme: base.scheme,
      hasAuthority: base.hasAuthority,
      userinfo: base.userinfo,
      host: base.host,
      hasPort: base.hasPort,
      port: base.port,
      path,
      hasQuery: ref.hasQuery,
      query: ref.query,
      hasFragment: ref.hasFragment,
      fragment: ref.fragment,
    }
  }

  normalizeComponents(t)
  return serialize(t)
}
